#!/usr/bin/env python3
"""Apply the reviewed final-manuscript patch once, then synchronize the canonical alias."""
from pathlib import Path
import base64, subprocess, zlib
ROOT=Path(__file__).resolve().parents[1]
PAPER=ROOT/'docs/paper/paper.md'
ALIAS=ROOT/'docs/paper/paper-draft.md'
MARKER='63%-71% under Jeffreys alpha=0.5 and 47%-53% under alpha=1'
PAYLOAD='''[... ELLIPSIZATION ...]'''

def main():
    text=PAPER.read_text(encoding='utf-8')
    if MARKER not in text:
        patch=zlib.decompress(base64.b64decode(PAYLOAD)).decode('utf-8')
        lines=patch.splitlines()
        lines[0]='--- docs/paper/paper.md'
        lines[1]='+++ docs/paper/paper.md'
        result=subprocess.run(['patch','-p0','--batch','--forward'],cwd=ROOT,input='\n'.join(lines)+'\n',text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
        if result.returncode:
            raise SystemExit('final paper patch failed:\n'+result.stdout)
        text=PAPER.read_text(encoding='utf-8')
    if MARKER not in text:
        raise SystemExit('final manuscript marker missing after patch')
    if any(ord(ch)<32 and ch not in '\n\t' for ch in text):
        raise SystemExit('control character found in final manuscript')
    ALIAS.write_text(text,encoding='utf-8')
    print('sync_final_paper: canonical final manuscript synchronized')
if __name__=='__main__': main()
